def f(expr):
    s = expr
    n = len(s)
    i = 0

    def skip_spaces():
        nonlocal i
        while i < n and s[i] == ' ':
            i += 1

    def parse_number():
        nonlocal i
        skip_spaces()
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i]) if start != i else 0

    def parse_factor():
        nonlocal i
        skip_spaces()
        if i < n and s[i] == '(':
            i += 1                     # '('
            val = parse_expr()
            skip_spaces()
            if i < n and s[i] == ')':
                i += 1                 # ')'
            return val
        return parse_number()

    def parse_term():
        nonlocal i
        val = parse_factor()
        while True:
            skip_spaces()
            if i < n and s[i] == '*':
                i += 1
                val *= parse_factor()
            else:
                break
        return val

    def parse_expr():
        nonlocal i
        val = parse_term()
        while True:
            skip_spaces()
            if i < n and s[i] in '+-':
                op = s[i]
                i += 1
                right = parse_term()
                if op == '+':
                    val += right
                else:
                    val -= right
            else:
                break
        return val

    return parse_expr()
